CREATE TABLE rol (nombre VARCHAR2(60) PRIMARY KEY, edicion_propia BOOLEAN NOT NULL);
CREATE TABLE rol_privilegio (rol_nombre VARCHAR2(60) NOT NULL REFERENCES rol(nombre), privilegio VARCHAR2(80) NOT NULL, PRIMARY KEY(rol_nombre, privilegio));
CREATE TABLE usuario (id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario VARCHAR2(80) NOT NULL UNIQUE, nombre VARCHAR2(150) NOT NULL, clave VARCHAR2(255) NOT NULL, rol_nombre VARCHAR2(60) NOT NULL REFERENCES rol(nombre));
CREATE TABLE lote (id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR2(30) NOT NULL UNIQUE, nombre VARCHAR2(150) NOT NULL, hectareas FLOAT(53) NOT NULL, cultivo VARCHAR2(80) NOT NULL, valle VARCHAR2(80) NOT NULL, campania_cerrada BOOLEAN NOT NULL, dosis_maxima_por_hectarea FLOAT(53) NOT NULL);
CREATE TABLE labor (id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, lote_id NUMBER(19) NOT NULL REFERENCES lote(id), tipo VARCHAR2(30) NOT NULL, fecha DATE NOT NULL, autor_id NUMBER(19) NOT NULL REFERENCES usuario(id), cantidad FLOAT(53) NOT NULL, observacion VARCHAR2(1000) NOT NULL, registrado_en TIMESTAMP NOT NULL, cliente_id VARCHAR2(80), CONSTRAINT uq_labor_cliente UNIQUE(autor_id,cliente_id));
CREATE INDEX idx_labor_lote ON labor(lote_id,fecha);
